def short(n):
    p = n.split()
    return p[0] + (' ' + '. '.join(x[0] for x in p[1:3]) + '.' if len(p) > 1 else '')


def main():
    src = json.load(open(SRC, encoding='utf-8'))
    regs = {d['id']: d for d in json.load(open(REGS, encoding='utf-8'))['docs'] if d.get('g') == 'ko'}
    people = []
    for g in src['groups']:
        for p in g.get('people') or []:
            q = {k: p.get(k) for k in ('name', 'role', 'emails', 'extra', 'reports_to', 'purpose', 'duties', 'kpi', 'contacts')}
            q['group'] = 'Сеть офисов продаж' if g.get('title') == 'Филиалы' or 'г. ' in str(p.get('extra') or '') else g.get('title')
            if q['group'] == 'Руководство отдела': q['group'] = 'ОП Рязань'
            q.update(FIX.get(p['name'], {}))
            people.append(q)
    people = [p for p in people if p['name'] not in DROP and p.get('group') != 'Fabrikant UZ']
    have = {p['name'] for p in people}
    people += [dict(x) for x in NEW if x['name'] not in have and x['name'] not in DROP]
    people += [dict(x) for x in LEFT if x['name'] not in have]
    for p in people:
        p.setdefault('status', 'работает'); p['short'] = short(p['name']); p['subst'] = SUBST.get(p['name'], '')
        if isinstance(p.get('duties'), list): p['duties'] = [re.sub(r',\s*Узбекистан(?=\.|$)', '', d) if isinstance(d, str) else d for d in p['duties']]   # 02.11.2026, Т. В.: Узбекистан убран
        p['zones'] = [z[0] for z in ZONES if p['short'].replace(' ', '') in (z[2] + ' ' + z[3] + ' ' + z[4]).replace(' ', '')]
        p['zones_lead'] = [z[0] for z in ZONES if p['short'].replace(' ', '') in z[2].replace(' ', '')]
        ids = list(INSTR_ALL)
        for rx, add in INSTR_ROLE:
            if re.search(rx, (p.get('role') or '') + ' ' + (p.get('group') or ''), re.I): ids += add
        if p.get('status') == 'уволен': ids = []
        p['instr'] = [{'id': i, 'title': regs[i]['title'], 'kind': regs[i].get('kind'), 'status': regs[i].get('status')} for i in dict.fromkeys(ids) if i in regs]
    order = ['Руководство', 'ОП Рязань', 'Ключевые клиенты', 'Отдел продаж', 'e-commerce', 'Направление e-commerce', 'Имя', 'Сеть офисов продаж', 'Fabrikant UZ', 'Не работают']
    people.sort(key=lambda p: (order.index(p['group']) if p['group'] in order else 99, p['name']))
    out = {'v': 1, 't': datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=3))).strftime('%Y-%m-%dT%H:%M'),
           'src': 'Утверждено Т. В. Сотрудник 02.11.2026. Функционал — по ответам руководителей (24–29.10, статусы Сотрудник, Сотрудник, Имя и Джановой — Сотрудник и Сотрудник 29.10); зоны — общий ответ Ю. А. Сотрудник 29.10 с решениями от 02.11; замещение — ответы 26–28.10, полная таблица запрошена до 09.11.',
           'zones': [{'n': z[0], 't': z[1], 'lead': z[2], 'part': z[3], 'dec': z[4], 'note': z[5]} for z in ZONES],
           'people': people, 'check': CHECK,
           'known_gone': ['Сотрудник Имя', 'Сотрудник Имя', 'Сотрудник Сотрудник']}   # 02.11: решено собственником — проверке штата не спрашивать «куда передан функционал»
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    json.dump(out, open(OUT, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    shutil.copy(OUT, HOST)
    print(json.dumps({'people': len(people), 'groups': sorted(set(p['group'] for p in people)), 'no_zone': [p['short'] for p in people if not p['zones']][:30]}, ensure_ascii=False))


if __name__ == '__main__':
    main()
